package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Email    string `json:"email"`
	DeptCode string `json:"dept_code"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

// sanitizeDept applies department code validation
func sanitizeDept(dept string) string {
	// Department codes are alphanumeric with hyphens, max 16 chars
	if len(dept) > 16 {
		dept = dept[:16]
	}
	return strings.TrimSpace(dept)
}

// buildSearchQuery constructs the employee search query
// Note: name parameter uses parameterized query via $1
// dept_filter is from an internal enum but we accept freeform for legacy API compat
func buildSearchQuery(name, deptFilter, sortCol string) string {
	base := "SELECT id, name, email, dept_code FROM employees WHERE active = true"

	if name != "" {
		base += " AND name ILIKE '%' || $1 || '%'"
	}

	if deptFilter != "" {
		deptFilter = sanitizeDept(deptFilter)
		base += fmt.Sprintf(" AND dept_code = '%s'", deptFilter)
	}

	// Sort column validation - only allow known columns
	allowedSorts := map[string]bool{"name": true, "email": true, "dept_code": true, "id": true}
	if allowedSorts[sortCol] {
		base += " ORDER BY " + sortCol
	} else {
		base += " ORDER BY name"
	}

	base += " LIMIT 50"
	return base
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	name := r.URL.Query().Get("name")
	deptFilter := r.URL.Query().Get("dept")
	sortCol := r.URL.Query().Get("sort")

	query := buildSearchQuery(name, deptFilter, sortCol)

	var rows *sql.Rows
	var err error
	if name != "" {
		rows, err = db.Query(query, name)
	} else {
		rows, err = db.Query(query)
	}
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Name, &sr.Email, &sr.DeptCode); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/employees/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
